          "invalid // LabClass not a sub class of CrossListed",
          "invalid // cannot instantiate interface types",
          "invalid // AcademicClass not a sub class of CrossListed",
          "I 21",
          "GOV60 // extra spaces okay",
          "ECO 1 // calls getStudents() based on dynamic type",
          "true",
